/**
 * Creates attributes for code and pre elements based on metadata and code highlighter.
 *
 * @param {object} metadata - An object containing metadata for the code.
 * @param {string} metadata.languageName - The name of the programming language.
 * @param {string} [metadata.title] - An optional title for the code block.
 * @param {string} [metadata.languageStringLiteral] - An optional string literal representing the language.
 * @param {object} codeHighlighter - An object representing the code highlighter.
 * @param {string} codeHighlighter.name - The name of the code highlighter.
 * @returns {object} An object containing attributes for pre and code elements.
 * @returns {object} return.preAttributes - Attributes for the pre element.
 * @returns {object} return.codeAttributes - Attributes for the code element.
 */
const createAttributes = (metadata, codeHighlighter) => {
  const { languageName, title, languageStringLiteral } = metadata;

  // Note: While something classless, such as `[data-code-grammar=languageName]`
  // would be nicer to look at, Prism uses the same language-X classes to target
  // nested styles. This is also the HTML5 spec suggestion for higlighting code.
  // By using a class for this plugin, consistence and compliance are ensured.
  const codeAttributes = {
    class: `language-${languageName} notranslate`,
    translate: `no`,
  };
  const preAttributes = {};

  if (languageStringLiteral)
    preAttributes[`data-code-language`] = languageStringLiteral;

  if (title) preAttributes[`data-code-title`] = title;

  if (codeHighlighter.name === 'prism')
    preAttributes[`data-code-preview`] = true;

  return { preAttributes, codeAttributes };
};

/**
 * Represents a node that triggers a sub-build process.
 *
 * @extends Node
 */
class SubBuildNode extends Node {

	static get type() {

		return 'SubBuild';

	}

	constructor( node, name, nodeType = null ) {

		super( nodeType );

		/**
		 * The node to be built in the sub-build.
		 *
		 * @type {Node}
		 */
		this.node = node;

		/**
		 * The name of the sub-build.
		 *
		 * @type {string}
		 */
		this.name = name;

		/**
		 * This flag can be used for type testing.
		 *
		 * @type {boolean}
		 * @readonly
		 * @default true
		 */
		this.isSubBuildNode = true;

	}

	generateNodeType( builder ) {

		if ( this.nodeType !== null ) return this.nodeType;

		builder.addSubBuild( this.name );

		const nodeType = this.node.getNodeType( builder );

		builder.removeSubBuild();

		return nodeType;

	}

	build( builder, ...params ) {

		builder.addSubBuild( this.name );

		const data = this.node.build( builder, ...params );

		builder.removeSubBuild();

		return data;

	}

}

/**
 * Creates a metadata extractor function for a given set of languages.
 *
 * @param {object} languages - An object mapping language names to their string literals.
 * @param {function(object): string} languages.languageName - The name of the language.
 * @param {function(object): object} node - The node to extract metadata from.
 * @returns {object} An object containing extracted metadata.
 * @returns {string} return.languageName - The name of the language of the node.
 * @returns {string|null} return.title - The title of the node, or null if not found.
 * @returns {string} return.languageStringLiteral - The string literal for the node's language.
 * @returns {Array<object>} return.highlightedLines - An array of objects representing highlighted lines.
 * @returns {Array<object>} return.insertedLines - An array of objects representing inserted lines.
 * @returns {Array<object>} return.deletedLines - An array of objects representing deleted lines.
 * @returns {Array<object>} return.foldedSections - An array of objects representing folded sections.
 */
const createMetadataExtractor = languages => node => {
  const languageName = getLanguageName(node);
  const meta = parseMeta(node.meta || '');
  const title = getMetaString(meta, 'title')?.value || null;
  const languageStringLiteral = languages[languageName] || '';
  const highlightedLines = getMetaRanges(meta, null);
  const insertedLines = getMetaRanges(meta, 'ins');
  const deletedLines = getMetaRanges(meta, 'del');
  const foldedSections = getMetaRangeBoundaries(meta, 'collapse');

  return {
    languageName,
    title,
    languageStringLiteral,
    highlightedLines,
    insertedLines,
    deletedLines,
    foldedSections,
  };
};

/**
 * Recursively fills the encode fence with characters.
 *
 * @param {Array<Array<string>>} fence - The current state of the fence.
 * @param {number} currentRail - The index of the current rail being filled.
 * @param {number} direction - The current direction of movement (1 for down, -1 for up).
 * @param {Array<string>} chars - The remaining characters to be placed.
 * @returns {Array<Array<string>>} The completed fence.
 */
const fillEncodeFence = ({
  fence,
  currentRail,
  direction,
  chars,
}) => {
  if (chars.length === 0) {
    // All chars have been placed on a fence.
    return fence;
  }

  const railCount = fence.length;

  // Getting the next character to place on a fence.
  const [letter, ...nextChars] = chars;
  const nextDirection = getNextDirection({
    railCount,
    currentRail,
    direction,
  });

  return fillEncodeFence({
    fence: fence.map(addCharToRail(currentRail, letter)),
    currentRail: currentRail + nextDirection,
    direction: nextDirection,
    chars: nextChars,
  });
};

